parameters.jsCode:
const agente =
  $input.first()?.json ?? {};

let cita = null;

try {
  cita =
    $('crear_cita_agenda_dz')
      .first()
      ?.json ?? null;
} catch {
  cita = null;
}

if (cita?.cita_creada !== true) {
  return [
    {
      json: agente,
    },
  ];
}

const fecha =
  String(
    cita.fecha_solicitada ?? ''
  ).trim();

const hora =
  String(
    cita.hora_inicio ?? ''
  ).trim();

const partesFecha =
  /^(\d{4})-(\d{2})-(\d{2})$/.exec(fecha);

const partesHora =
  /^(\d{2}):(\d{2})$/.exec(hora);

if (!partesFecha || !partesHora) {
  throw new Error(
    'DZ_900_POST_COMMIT_FECHA_HORA_INVALIDA'
  );
}

const anio =
  Number(partesFecha[1]);

const mes =
  Number(partesFecha[2]);

const dia =
  Number(partesFecha[3]);

const hora24 =
  Number(partesHora[1]);

const minuto =
  Number(partesHora[2]);

const fechaUtc =
  new Date(
    Date.UTC(
      anio,
      mes - 1,
      dia,
      12,
      0,
      0
    )
  );

const dias = [
  'domingo',
  'lunes',
  'martes',
  'miércoles',
  'jueves',
  'viernes',
  'sábado',
];

const meses = [
  '',
  'enero',
  'febrero',
  'marzo',
  'abril',
  'mayo',
  'junio',
  'julio',
  'agosto',
  'septiembre',
  'octubre',
  'noviembre',
  'diciembre',
];

const hora12 =
  hora24 % 12 || 12;

const periodo =
  hora24 < 12
    ? 'a. m.'
    : 'p. m.';

const horaTexto =
  `${hora12}:` +
  `${String(minuto).padStart(2, '0')} ` +
  periodo;

const procedimiento =
  String(
    cita.nombre_procedimiento ?? ''
  ).trim();

const clinicaId =
  String(
    cita.clinica_id ?? ''
  ).trim();

const clinica =
  clinicaId === ''
    ? ''
    : clinicaId.charAt(0).toUpperCase() +
      clinicaId.slice(1);

const doctor =
  String(
    cita.doctor_nombre ?? ''
  ).trim();

let output =
  `Perfecto, tu cita para ${procedimiento} ` +
  `quedó agendada para el ` +
  `${dias[fechaUtc.getUTCDay()]} ${dia} de ${meses[mes]} ` +
  `a las ${horaTexto}`;

if (clinica !== '') {
  output +=
    ` en Dental Zone ${clinica}`;
}

if (doctor !== '') {
  output +=
    ` con ${doctor}`;
}

output += '.';

return [
  {
    json: {
      ...agente,
      output,

      post_commit: {
        tipo: 'cita_creada',
        cita_id: cita.cita_id,
      },
    },
  },
];

const salida =
  $input.first()?.json ?? {};

const pasos =
  Array.isArray(salida.intermediateSteps)
    ? salida.intermediateSteps
    : [];

const herramientasTransferencia =
  new Set([
    'transferir_emergencia_humana_dz',
    'transferir_emergencia_fuera_horario_dz',
  ]);

const transferenciaCompletada =
  pasos.some(paso => {
    const herramienta =
      paso?.action?.tool;

    if (
      !herramientasTransferencia.has(
        herramienta
      )
    ) {
      return false;
    }

    let observacion =
      paso?.observation ?? null;

    if (typeof observacion === 'string') {
      try {
        observacion =
          JSON.parse(observacion);
      } catch {
        return false;
      }
    }

    const resultados =
      Array.isArray(observacion)
        ? observacion
        : [observacion];

    return resultados.some(
      resultado =>
        resultado
          ?.transferencia
          ?.completada === true
    );
  });

if (transferenciaCompletada) {
  return [];
}

return [
  {
    json: salida,
  },
];
